import * as React from "react"
import Outcome from "../../components/Outcome"
import Seo from "../../components/Seo"

/**
 * A purchase that did not complete — MTC-FCS-008.
 *
 * Covers both the abandoned checkout and the declined card, because from here
 * they are the same situation: no money moved, nothing was set up, and the
 * only useful next step is trying again. Guessing which one happened would
 * mean telling some people their card was declined when they simply closed
 * the tab.
 */
const PurchaseFailedPage = () => (
  <Outcome
    tone="neutral"
    title="No payment was taken"
    lead="The payment did not go through, so nothing has been charged and nothing has been set up. Your website is exactly as you left it."
    points={[
      "No charge was made to your card",
      "Your draft is saved in this browser",
      "No card details were stored",
    ]}
    primary={{ href: "/buy", label: "Try again" }}
    secondary={{ href: "/website-builder", label: "Back to my website" }}
  />
)

export const Head = () => <Seo title="Payment not completed" />

export default PurchaseFailedPage
